// Per-client state. That's it — two numbers.
// { tokens: number, lastRefillMs: number }

const LIMIT = 100;        // bucket capacity  → burst tolerance
const REFILL_PER_SEC = 10; // sustained rate

function refill(state, nowMs) {
  const elapsedSec = (nowMs - state.lastRefillMs) / 1000;
  const topUp = elapsedSec * REFILL_PER_SEC;

  return {
    tokens: Math.min(LIMIT, state.tokens + topUp), // never exceed capacity
    lastRefillMs: nowMs,
  };
}

function tryConsume(state, nowMs) {
  const s = refill(state, nowMs);

  if (s.tokens < 1) {
    const waitSec = (1 - s.tokens) / REFILL_PER_SEC;
    return { allowed: false, state: s, retryAfterSec: Math.ceil(waitSec) };
  }

  return {
    allowed: true,
    state: { ...s, tokens: s.tokens - 1 },
    remaining: Math.floor(s.tokens - 1),
  };
}

// TWO gateway nodes, one shared Redis, same client:
//
//   node A: GET bucket → 1 token left
//   node B: GET bucket → 1 token left   ← same value
//   node A: SET tokens = 0   → ALLOW
//   node B: SET tokens = 0   → ALLOW    ← over-admitted
//
// Over-admission scales with node count, and it happens
// hardest under the exact load you were defending against.

const SCRIPT = `
  local tokens = tonumber(redis.call('HGET', KEYS[1], 'tokens') or ARGV[1])
  local last   = tonumber(redis.call('HGET', KEYS[1], 'last')   or ARGV[4])
  local now, rate, cap = tonumber(ARGV[4]), tonumber(ARGV[2]), tonumber(ARGV[1])

  tokens = math.min(cap, tokens + ((now - last) / 1000) * rate)

  if tokens < 1 then return {0, 0} end

  redis.call('HSET', KEYS[1], 'tokens', tokens - 1, 'last', now)
  redis.call('EXPIRE', KEYS[1], ARGV[3])
  return {1, math.floor(tokens - 1)}
`;

async function allow(redis, clientId) {
  const [ok, remaining] = await redis.eval(
    SCRIPT, 1, `rl:${clientId}`,
    LIMIT, REFILL_PER_SEC, 3600, Date.now()
  );
  return { allowed: ok === 1, remaining };
}

async function middleware(req, res, next) {
  try {
    const { allowed, remaining } = await allow(redis, keyFor(req));

    res.set('X-RateLimit-Limit', LIMIT);
    res.set('X-RateLimit-Remaining', remaining);

    if (!allowed) {
      // jitter so throttled clients don't all return in the same millisecond
      res.set('Retry-After', 1 + Math.floor(Math.random() * 5));
      return res.status(429).json({ error: 'rate limited' });
    }
    next();
  } catch (err) {
    // Redis unreachable: fail OPEN so a limiter outage isn't an API outage.
    if (isAuthEndpoint(req)) return res.status(503).end(); // ...except here
    next();
  }
}
